if(!window.location.search)window.location.replace('./.preview/lobby-preview.html');
import {unlockedStage,hasClearedStage} from './stage-access.js?v=1.7.15';
import {prepareBattleSprites} from './sprite-assets.js?v=1.7.15';
import {skillCard,ownedSkills} from './skill-ui.js?v=1.7.15';
import {MODES,SKILLS,UNIT_SKILLS,RECIPES,CHARACTERS,STAGES,UPGRADES,QUESTS,byId,upgradeCost} from './data.js?v=1.7.15';
import {loadSave,persist,buyUpgrade,buyResearch,researchResetPreview,resetResearch,questProgress,claimQuest,settleRun} from './store.js?v=1.7.15';
import {Game} from './engine.js?v=1.7.15';
import {Renderer} from './render.js?v=1.7.15';
import {portrait,cityArt,icon} from './art.js?v=1.7.15';
import {bulkSaleItems,bulkSellGear,rerollGear,craftGear,craftCandidates,REROLL_COST,GRADES,SLOTS,gearName,calculateStats,equipGear,unequipGear,moveGear,sellGear,isEquipped,drawGear,enhanceGear,autoCraftGear,ENHANCE_CHANCES,enhancementMultiplier} from './equipment.js?v=1.7.15';
import {equipmentMarkup,newGearView,fusionMarkup} from './gear-ui.js?v=1.7.15';
const gearView=newGearView();let pendingSale=null,pendingBulk=null,pendingCraft=null,pendingReroll=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal-root');
const save=loadSave();try{const old=JSON.parse(localStorage.getItem('nightfall.save.v1'));if([1,2,3].includes(old?.version)||(old&&JSON.stringify(old.questGearClaimed||[])!==JSON.stringify(save.questGearClaimed)))persist(save);}catch{/* Leave unreadable storage untouched. */}let view=['mission','inventory','research','codex','characters','quests'].includes(new URLSearchParams(window.location.search).get('view'))?new URLSearchParams(window.location.search).get('view'):'mission',stageId=unlockedStage(new URLSearchParams(window.location.search).get('stage'),STAGES,save.maxStage)||1,mode='normal',accelerated=false,game=null,renderer=null,result=null,lastFrame=0,hudTick=0,levelSignature='',audio=null,joystick=null;
let starting=false,startGeneration=0;
const keys=new Set();let modalOpen=false,selectedRunSkill=null,runSkillSignature='';
const fmt=n=>Math.floor(n).toLocaleString('ko-KR');
const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function writeSave(){if(!persist(save))toast('저장 공간에 접근할 수 없습니다. 이번 기록은 브라우저를 닫으면 사라질 수 있어요.','error');}
function toast(message,type='normal'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),4200);}
function sound(type){if(!save.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);const t=audio.currentTime;osc.type=type==='hurt'?'sawtooth':'sine';osc.frequency.setValueAtTime(type==='shoot'?185:type==='hurt'?90:type==='levelup'?520:720,t);osc.frequency.exponentialRampToValueAtTime(type==='shoot'?70:type==='hurt'?40:1000,t+.09);gain.gain.setValueAtTime(type==='shoot'?.018:.055,t);gain.gain.exponentialRampToValueAtTime(.001,t+.12);osc.start(t);osc.stop(t+.13);}catch{}}
const credits=(n=save.credits)=>`<span class="currency-symbol">${icon('diamond')}</span> ${fmt(n)} <small>에테르</small>`;
function nav(){const entries=[['mission','grid','작전 본부'],['inventory','grid','장비 · 창고'],['research','flask','각성 연구'],['codex','book','초능력 도감'],['characters','user','각성자'],['quests','quest','해금 퀘스트']];return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="mission"><img src="./mark.svg" alt=""/><span>NIGHTFALL<small>각성의 밤</small></span></a><div class="nav-label">CONTROL CENTER</div><nav aria-label="주 메뉴">${entries.map(([id,i,label])=>`<button class="nav-item ${view===id?'active':''}" data-action="nav" data-view="${id}" aria-label="${label}" title="${label}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='codex'?`<small>${save.discovered.length}</small>`:id==='quests'&&QUESTS.some(q=>questProgress(save,q)>=q.target&&!save.claimed.includes(q.id))?'<i class="notification-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="signal"><i></i> 시스템 온라인</div><p>도시는 아직, 잠들지 않았다.</p><div class="build-label">PROJECT NIGHTFALL <span>v1.7.15</span></div></div></aside>`;}
function shell(content){app.innerHTML=`<div class="shell">${nav()}<div class="main-shell"><header class="topbar"><div class="breadcrumb">각성자 관리국 <span>/</span> <strong>${({mission:'작전 본부',inventory:'장비 · 창고',research:'각성 연구',codex:'초능력 도감',characters:'각성자',quests:'해금 퀘스트'})[view]}</strong></div><div class="top-actions"><div class="credits">${credits()}</div><span class="divider"></span><button class="icon-button" data-action="sound" aria-label="${save.sound?'소리 끄기':'소리 켜기'}">${icon(save.sound?'sound':'mute')}</button><button class="icon-button help-button" data-action="help" aria-label="게임 안내">?</button><span class="profile">A</span></div></header><main>${content}</main><footer class="footer"><span><i></i> 모든 기록은 이 브라우저에 자동 저장됩니다. 캐시·사이트 데이터 삭제 시 저장 데이터가 삭제될 수 있습니다.</span><span>© 2026 HOJUN. All rights reserved</span></footer></div></div>`;}
function pageHeader(){return '';}
function render(){if(game&&game.state!=='ended')return;const templates={mission:mission,inventory:inventoryPage,research:research,codex:codex,characters:characters,quests:quests};shell(templates[view]());prepareBattleSprites(byId(CHARACTERS,save.character)?.sprite).catch(()=>{});}
function mission(){if(mode==='endless'&&!hasClearedStage(save,stageId))mode='normal';const c=byId(CHARACTERS,save.character),s=byId(STAGES,stageId),stats=calculateStats(save,c);return `${pageHeader('OPERATIONS / 01','다시, 밤 속으로.','균열을 넘어 살아남으세요. 당신의 다음 각성이 기다리고 있습니다.',`<span class="status-pill"><i></i> 출격 준비 완료</span>`)}<div class="operation-heading"><a class="button" href="./.preview/lobby-preview.html">← 로비로 가기</a></div><div class="mission-grid"><section class="stage-panel panel"><div class="stage-art">${cityArt()}<div class="art-grain"></div><div class="art-top"><span class="tag">${s.area}</span><span class="live-tag"><i></i> 균열 활성</span></div><div class="art-caption"><span class="eyebrow">THE CITY AFTER DARK</span><h2>${s.name}</h2><p>${s.desc}</p></div><div class="sector-number">${String(s.id).padStart(2,'0')}</div></div><div class="stage-data"><div>${icon('clock')}<span>작전 시간<strong>${mode==='endless'?'∞':accelerated?'05:00':'10:00'} <small>실제 시간</small></strong></span></div><div>${icon('target')}<span>보스 출현<strong>02:00 <small>간격</small></strong></span></div><div>${icon('diamond')}<span>클리어 보너스<strong>+${mode==='endless'?0:s.reward} <small>에테르</small></strong></span></div></div><div class="mode-select"><span>작전 모드</span><div class="mode-buttons"><button class="mode-toggle ${accelerated?'selected':''}" data-action="toggle-mode" data-id="accelerated" aria-pressed="${accelerated}">가속 ${accelerated?'ON':'OFF'}</button><button class="mode-toggle ${mode==='endless'?'selected':''}" data-action="toggle-mode" data-id="endless" aria-pressed="${mode==='endless'}" ${hasClearedStage(save,stageId)?'':'disabled title="이 스테이지 클리어 후 이용할 수 있습니다"'}>무한 ${hasClearedStage(save,stageId)?(mode==='endless'?'ON':'OFF'):'🔒'}</button></div><p>가속: 스테이지 시간·적 등장 2배 · 무한: 제한 없이 진행, 클리어 보너스 없음</p></div><div class="stage-select"><span>작전 구역</span><div class="sector-buttons">${STAGES.map(st=>`<button data-action="stage" data-id="${st.id}" class="sector ${stageId===st.id?'selected':''}" ${st.id>save.maxStage?'disabled':''} aria-label="${st.name}${st.id>save.maxStage?' · 이전 구역 클리어 필요':''}" title="${st.name}">${st.id>save.maxStage?icon('lock'):String(st.id).padStart(2,'0')}<span>${st.name}</span></button>`).join('')}</div></div></section><aside class="operative-panel panel"><div class="panel-top"><span class="eyebrow">SELECTED AWAKENED</span><button class="text-button" data-action="nav" data-view="characters">변경 ${icon('chevron')}</button></div><div class="operative-art">${portrait(c,true)}<span class="character-tier">CLASS <b>A</b></span></div><div class="operative-info"><span class="mini-tag">기본 각성자${c.skill?' · 특수 능력 보유':''}</span><h2>${c.name}${c.tag!==c.name?`<span>${c.tag}</span>`:''}</h2><div class="character-stats"><span>체력 <b>${Math.round(stats.hp)}</b></span><span>공격 <b>${Math.round(stats.attack)}</b></span><span>이동 <b>${Math.round(stats.speed)}</b></span></div><div class="starting-power">${icon('bolt')} 신체 강화${c.skill?` <span>+ ${byId(SKILLS,c.skill).name}</span>`:' <span>기본 능력</span>'}</div><button class="button primary deploy-button" data-action="start"><span>작전 시작</span>${icon('arrow')}</button><p class="deploy-note">초능력 초기화 · 장착 장비 ${Object.keys(save.equipped).length}/6 유지</p><button class="text-button loadout-link" data-action="nav" data-view="inventory">장비 확인 · 인벤토리 ${icon('arrow')}</button></div></aside></div><section class="overview-grid"><button class="overview-card" data-action="nav" data-view="research"><div class="overview-icon">${icon('flask')}</div><div><span>영구 성장</span><h3>각성 연구</h3><p>다음 출격은 조금 더 강하게</p></div>${icon('arrow')}</button><button class="overview-card" data-action="nav" data-view="codex"><div class="overview-icon">${icon('book')}</div><div><span>${save.discovered.length} / ${SKILLS.length} 발견</span><h3>초능력 도감</h3><p>발견한 능력의 가능성을 확장하세요</p></div>${icon('arrow')}</button><button class="overview-card" data-action="nav" data-view="quests"><div class="overview-icon">${icon('quest')}</div><div><span>${save.claimed.length} / ${QUESTS.length} 완료</span><h3>새로운 각성자</h3><p>그들의 이야기를 시작하세요</p></div>${icon('arrow')}</button></section><section class="briefing"><div><span class="briefing-icon">${icon('bolt')}</span><strong>작전 브리핑</strong><span>이동하고, 각성하고, 살아남으세요.</span></div><div class="key-guide"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd><span>이동</span><kbd>SPACE</kbd><span>회피</span><span class="auto-badge">자동 공격</span></div></section>${save.history.length?`<div class="recent-record"><span class="eyebrow">LAST OPERATION</span><span>${byId(STAGES,save.history[0].stage)?.name} · ${clock(save.history[0].time)} · ${fmt(save.history[0].kills)} 처치</span><span>+${save.history[0].earned} 에테르</span></div>`:''}`;}
function research(){return `${pageHeader('AWAKENING LAB','남겨진 힘, 새로운 가능성.','전투에서 모은 에테르로 다음 출격의 기본 능력을 강화합니다.')}<div class="research-banner"><div class="research-orb">${icon('flask')}</div><div><span class="eyebrow">AVAILABLE ETHER</span><h2>${fmt(save.credits)} <small>에테르</small></h2><p>전투 중 획득 + 스테이지 클리어 보너스</p></div><span class="tag">영구 적용</span></div><div class="upgrade-grid">${UPGRADES.map(u=>{const l=save.upgrades[u.id]||0,max=l>=u.max,requires=u.requires&&(save.upgrades[u.requires]||0)<2,cost=upgradeCost(u,l);return `<article class="upgrade-card panel"><div class="upgrade-symbol">${u.icon}</div><span class="card-level">${String(l).padStart(2,'0')} <small>/ ${u.max}</small></span><h3>${u.name}</h3><p>${u.desc}</p><div class="level-pips">${Array.from({length:u.max},(_,i)=>`<i class="${i<l?'filled':''}"></i>`).join('')}</div><button class="button ${!max&&!requires&&save.credits>=cost?'secondary':''}" data-action="upgrade" data-id="${u.id}" ${max||requires||save.credits<cost?'disabled':''}>${max?'연구 완료':requires?'가능성 확장 Lv.2 필요':`${icon('diamond')} ${fmt(cost)} 에테르 <span>연구</span>`}</button></article>`;}).join('')}</div><div class="info-strip">${icon('book')} 특정 초능력의 등장 확률과 기본 성능은 <button class="text-button" data-action="nav" data-view="codex">초능력 도감 ${icon('arrow')}</button>에서 연구할 수 있습니다.</div>`;}
function codex(){return `${pageHeader('ABILITY ARCHIVE','당신이 깨운 능력들.','출격 중 발견한 능력을 연구하세요. 융합 능력은 조합으로만 획득하며 등장 가중치 연구가 적용되지 않습니다.',`<span class="count-badge">${save.discovered.length} <small>/ ${SKILLS.length}</small></span>`)}<section class="codex-recipes"><h2>조합법</h2>${fusionMarkup(RECIPES,SKILLS)}</section><div class="research-reset-all"><span>초능력 연구 초기화: 등장 가중치와 기본 성능의 투자 비용 전액 환급</span><button class="button" data-action="research-reset" data-id="all" ${researchResetPreview(save).count===0?'disabled':''}>전체 초기화</button></div><div class="codex-legend"><span><i></i> 발견한 초능력</span><span>등장 가중치 +25% / 연구 단계 · 기본 성능 +12% / 연구 단계</span></div><div class="codex-grid">${SKILLS.map(s=>{const known=save.discovered.includes(s.id),r=save.research[s.id]||{weight:0,power:0};return `<article class="skill-card panel ${known?'':'undiscovered'}" style="--skill-color:${s.color}"><div class="skill-card-head"><span class="skill-symbol">${known?s.icon:icon('lock')}</span><span class="tag">${s.type}</span></div><span class="eyebrow">${s.en}</span><h3>${s.name}</h3><p>${s.desc}</p>${skillCard(save,s.id,1)}${known?`<div class="research-lines">${[['weight','등장 가중치',25],['power','기본 성능',12]].filter(([kind])=>(!s.fusion||kind!=='weight')&&(!['time','chronos'].includes(s.id)||kind!=='power')).map(([kind,label,n])=>`<div><span>${label}<b>+${r[kind]*n}%</b></span><button data-action="skill-research" data-id="${s.id}" data-kind="${kind}" ${r[kind]>=5||save.credits<60+r[kind]*70?'disabled':''}>${r[kind]>=5?'MAX':`${icon('diamond')} ${60+r[kind]*70} +`}</button></div>`).join('')}</div>${['time','chronos'].includes(s.id)?'<p class="research-locked">성능 강화 불가</p>':''}<button class="button research-reset-button" data-action="research-reset" data-id="${s.id}" ${researchResetPreview(save,s.id).count?'':'disabled'}>이 능력 초기화</button>`:'<div class="locked-note">출격 중 획득하면 연구가 해금됩니다</div>'}</article>`;}).join('')}</div>`;}
function characters(){return `${pageHeader('AWAKENED PERSONNEL','각자의 이유로, 같은 밤으로.','모든 각성자는 강화된 신체를 지닙니다. 퀘스트를 완수해 특별한 능력자를 만나세요.')}<div class="characters-grid">${CHARACTERS.map(c=>{const unlocked=save.unlocked.includes(c.id),selected=save.character===c.id,q=QUESTS.find(q=>q.character===c.id);return `<article class="character-card panel ${selected?'chosen':''} ${unlocked?'':'locked-character'}"><div class="character-card-art">${portrait(c)}${!unlocked?`<span class="art-lock">${icon('lock')}</span>`:''}</div><div class="character-card-info"><h2>${c.name}</h2><div class="character-trait">${c.stats}</div><button class="button ${selected?'secondary':unlocked?'primary':''}" data-action="${unlocked?'character':'nav'}" data-id="${c.id}" data-view="quests">${selected?`${icon('check')} 선택됨`:unlocked?'각성자 선택':`퀘스트: ${q.title} ${icon('chevron')}`}</button></div></article>`;}).join('')}</div>`;}
function quests(){return `${pageHeader('FIELD ASSIGNMENTS','생존의 끝에서, 누군가를 만나다.','작전 기록은 누적됩니다. 퀘스트 보상을 수령하면 새 각성자와 에테르, 지정 장비를 획득합니다.')}<div class="quest-list">${QUESTS.map((q,i)=>{const n=Math.min(q.target,questProgress(save,q)),done=save.claimed.includes(q.id),ready=n>=q.target,c=byId(CHARACTERS,q.character);return `<article class="quest-card panel"><div class="quest-index">${String(i+1).padStart(2,'0')}</div><div class="quest-content"><p>${q.desc}</p><div class="quest-progress"><div><i style="width:${n/q.target*100}%"></i></div><span>${n} / ${q.target}</span></div></div><div class="quest-reward">${c?`<span class="mini-tag">각성자 해금</span><strong>${c.name}</strong>`:'<span class="mini-tag">보급 지원</span>'}${q.gearReward?`<strong class="quest-gear-reward">${q.gearReward.rarity.toUpperCase()} · ${gearName(q.gearReward)}</strong>`:''}<span>${icon('diamond')} ${q.reward} 에테르</span></div><button class="button ${ready&&!done?'primary':''}" data-action="claim" data-id="${q.id}" ${done||!ready?'disabled':''}>${done?`${icon('check')} 수령 완료`:ready?'보상 수령':'진행 중'}</button></article>`;}).join('')}</div><div class="info-strip">${icon('target')} 누적 처치 ${fmt(save.stats.kills)} · 보스 처치 ${save.stats.bosses} · 클리어 ${save.stats.clears} · 총 출격 ${save.stats.runs}</div>`;}
function help(){openModal(`<div class="modal-heading"><span class="eyebrow">FIELD MANUAL</span><h2>각성과 장비, 두 가지 성장</h2><button class="icon-button modal-close" data-action="close" aria-label="닫기">${icon('close')}</button></div><div class="help-steps"><div><b>01</b><p><strong>자동 공격과 이동</strong>WASD / 방향키 이동, Space 회피, Esc / P 일시정지, I 장비창. 모바일에서는 이동 패드와 회피 버튼을 사용합니다.</p></div><div><b>02</b><p><strong>스킬 융합</strong>경험치로 레벨을 올려 초능력을 선택하세요. 아래 조합의 두 능력이 각각 Lv.10이 되면 레벨업 선택지에서 융합을 선택할 수 있습니다. 소비한 원본 능력은 해당 전투에서 다시 등장하지 않습니다.</p></div><div><b>03</b><p><strong>부위별 영구 장비</strong>무기·방어구·헬멧·신발·장갑·코어를 하나씩 장착합니다. 새 장비는 미장착 상태로 보관됩니다. 전투 중에도 장비창에서 교체할 수 있고 시간이 멈춥니다. 로비에서는 판매와 창고 수납이 가능합니다.</p></div><div><b>04</b><p><strong>등급과 옵션</strong>C → U → EL → SP → UQ → EP → LE 순으로 수치가 높아집니다. EP·LE는 같은 부위와 등급 장비 3개로 제작합니다. 실패해도 메인은 유지되며 재료 2개와 에테르는 소모됩니다.</p></div><div><b>05</b><p><strong>보스와 보상</strong>2·4·6·8분 중간보스와 10분 최종보스를 모두 처치하면 클리어합니다. 에테르는 귀환·사망해도 정산됩니다. 장비·장착 상태는 획득과 변경 즉시 저장되며 다음 출격에도 유지됩니다.</p></div></div>${fusionMarkup(RECIPES,SKILLS)}<button class="button primary full-width" data-action="close">확인 ${icon('check')}</button>`);}
function openModal(html){modalOpen=true;modal.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${game?'작전 메뉴':'게임 안내'}" tabindex="-1">${html}</section></div>`;modal.querySelector('.modal').focus();}
function closeModal(){modalOpen=false;modal.innerHTML='';}
function battleLoading(error=false){
  app.innerHTML=`<main class="battle-loading"><section class="loading-panel panel" aria-labelledby="loading-title"><img src="./mark.svg" alt="" width="48" height="48"><span class="eyebrow">NIGHTFALL</span><h1 id="loading-title">${error?'전투 준비를 완료하지 못했습니다':'작전 구역에 진입하는 중'}</h1><p>${error?'연결 상태를 확인한 뒤 다시 시도해 주세요.':'몬스터와 각성자의 이미지를 준비하고 있습니다.'}</p>${error?'': '<progress id="battle-load-progress" max="100" value="0" aria-label="전투 이미지 준비율"></progress><p id="battle-load-status" role="status" aria-live="polite">0% · 이미지 준비 중</p>'}<p class="loading-note">모든 이미지 준비가 끝나면 전투가 시작됩니다.</p><div class="loading-actions">${error?'<button class="button primary" data-action="start">다시 시도</button>':''}<button class="button" data-action="nav" data-view="mission">로비로 돌아가기</button></div></section></main>`;
}
async function start(){
  if(starting||(game&&game.state!=='ended'))return;
  if(mode==='endless'&&!hasClearedStage(save,stageId))mode='normal';
  starting=true;const generation=++startGeneration;
  closeModal();renderer=null;keys.clear();battleLoading();
  try{await prepareBattleSprites(byId(CHARACTERS,save.character)?.sprite,(ready,total)=>{
    if(generation!==startGeneration)return;
    const progress=document.querySelector('#battle-load-progress'),status=document.querySelector('#battle-load-status');
    if(progress)progress.value=Math.round(ready/total*100);
    if(status)status.textContent=`${Math.round(ready/total*100)}% · ${ready} / ${total} 이미지 준비`;
  });}
  catch{if(generation===startGeneration)battleLoading(true);return;}
  finally{if(generation===startGeneration)starting=false;}
  if(generation!==startGeneration)return;
  closeModal();sound('start');result=null;selectedRunSkill=null;runSkillSignature='';keys.clear();joystick=null;game=new Game(save,stageId,{onEvent:gameEvent,mode,accelerated});renderer=null;levelSignature='';app.innerHTML=`<section class="game-screen"><canvas id="arena" aria-label="NIGHTFALL 전투 화면. WASD 이동, Space 회피, Esc 일시정지"></canvas><div class="game-top"><div class="game-identity"><img src="./mark.svg" alt=""/><div><span class="eyebrow">SECTOR ${String(stageId).padStart(2,'0')}</span><strong>${game.stage.name}</strong></div></div><div class="timer-block"><span id="phase-label">첫 번째 보스까지</span><strong id="timer">00:00</strong><div class="timeline"><i id="time-progress"></i><span></span></div></div><div class="game-actions"><span class="run-credits">${icon('diamond')}<b id="run-credit">0</b></span><button class="button" data-action="auto-select" id="auto-select-button">자동 선택 OFF</button><button class="icon-button" data-action="pause" aria-label="일시정지">${icon('pause')}</button></div></div><div id="boss-bars"></div><div class="game-left"><div class="player-card"><div class="player-card-top"><span>${game.character.name}</span><b id="level">Lv.1</b></div><div class="health-track"><i id="health-fill"></i><span id="health-text"></span></div><div class="xp-track"><i id="xp-fill"></i></div><div class="player-card-bottom"><span>신체 강화</span><span id="kill-count">0 처치</span></div></div><div id="run-skills"></div></div><div class="game-bottom"><div class="game-controls"><span><kbd>WASD</kbd> 이동</span><span><kbd>SPACE</kbd> 회피</span><span><kbd>ESC</kbd> 일시정지</span><span><kbd>I</kbd> 장비</span></div><div class="dash-indicator"><span id="dash-label">회피 준비</span><div><i id="dash-fill"></i></div></div><button class="equipment-button" data-action="equipment">${icon('grid')} 장비 <b id="item-count">0</b></button></div><div class="touch-controls"><div id="joystick" aria-label="이동 패드"><i></i></div><button id="touch-dash" aria-label="회피">${icon('bolt')}<span>회피</span></button></div><div id="game-banner" aria-live="polite"></div></section>`;renderer=new Renderer(document.querySelector('#arena'));toast('작전 개시 · 초록 경험치를 모아 초능력을 각성하세요.');updateHud();}
let bannerTimeout;
function banner(text,sub=''){const el=document.querySelector('#game-banner');if(!el)return;el.innerHTML=`<strong>${text}</strong><span>${sub}</span>`;el.classList.add('show');clearTimeout(bannerTimeout);bannerTimeout=setTimeout(()=>el.classList.remove('show'),3500);}
function gameEvent(e){if(['shoot','hurt','levelup','item','skill'].includes(e.type))sound(e.type);if(['discover','item','equipment','fusion'].includes(e.type))writeSave();if(e.type==='boss')banner('WARNING · 보스 출현',e.name);if(e.type==='bosskill')banner('보스 격파',`${e.name} · 체력 20% 회복 · 전리품 획득`);if(e.type==='item')toast(e.item.autoSold?`${e.item.rarity.toUpperCase()} 자동 판매 · +${GRADES[e.item.rarity].sell} 에테르`:`${e.item.rarity.toUpperCase()} 장비 획득 · ${gearName(e.item)} — 인벤토리에서 장착하세요 (I)`);if(e.type==='fusion'){banner('초능력 융합',byId(SKILLS,e.id).name);toast(`융합 완성 · ${byId(SKILLS,e.id).name}`);}if(e.type==='levelreward')toast('모든 능력을 완성했습니다 · +1,000 에테르');if(e.type==='time')banner('TIME STOP','보스는 절반의 시간 동안 정지합니다');if(e.type==='magnet')banner('에테르 수집기','전장의 드롭을 끌어옵니다');if(e.type==='revive')banner(e.source==='healingfactor'?'힐링팩터':'불사조의 잔재','부활 · 체력 60% 회복');if(e.type==='end'){result=settleRun(save,game);writeSave();queueMicrotask(showResult);}}
function updateHud(){if(!game||!renderer)return;const g=game;const text=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value;};text('timer',clock(g.time));text('auto-select-button',`자동 선택 ${g.autoSelect?'ON':'OFF'}`);text('phase-label',g.mode!=='endless'&&g.time>=600?'남은 보스를 처치하세요':`${MODES[g.mode].name}${g.accelerated?' + 가속':''} · 다음 보스 ${clock((Math.floor(g.time/120)+1)*120)}`);text('run-credit',fmt(g.credits));text('level','Lv.'+g.level);text('health-text',`${Math.ceil(g.player.hp)} / ${Math.round(g.stats.hp)}`);text('kill-count',`${g.kills} 처치`);text('item-count',Object.keys(save.equipped).length+'/6');text('dash-label',g.dashCooldown<=0?'회피 준비':`회피 ${g.dashCooldown.toFixed(1)}s`);const style=(id,width)=>{const e=document.getElementById(id);if(e)e.style.width=width+'%';};style('health-fill',g.player.hp/g.stats.hp*100);style('xp-fill',g.xp/g.nextXp*100);style('time-progress',(g.mode==='endless'?g.time%600:g.time)/600*100);style('dash-fill',(1-g.dashCooldown/(g.specialGrade('dash')==='le'?1:3.2))*100);const skillSignature=JSON.stringify(g.skills);if(runSkillSignature!==skillSignature){runSkillSignature=skillSignature;document.querySelector('#run-skills').innerHTML=Object.entries(g.skills).map(([id,l])=>{const s=byId(SKILLS,id);return `<span class="run-skill" tabindex="0" aria-label="${s.name} Lv.${l}. ${s.desc}" title="${s.name} Lv.${l} — ${s.desc}" style="--skill-color:${s.color}">${s.icon}<b>${l}</b></span>`;}).join('');}document.querySelector('#boss-bars').innerHTML=g.enemies.filter(e=>e.boss).map(e=>`<div class="boss-bar"><span>${e.name}<small>${Math.ceil(e.hp)} / ${e.maxHp}</small></span><div><i style="width:${e.hp/e.maxHp*100}%"></i></div></div>`).join('');if(g.state==='levelup'){const signature=g.level+'|'+g.offers.join(',')+'|'+g.picksLeft;if(levelSignature!==signature){levelSignature=signature;levelModal();}}}
function levelModal(){const g=game;openModal(`<div class="level-heading"><span class="eyebrow">AWAKENING · LEVEL ${g.level}</span><h2>잠들어 있던 힘이 깨어납니다.</h2><p>${g.offers.length}개의 가능성. <strong>${g.picksLeft}개</strong>의 초능력을 선택하세요.</p></div><div class="ability-choices">${g.offers.map(id=>{const s=byId(SKILLS,id)||byId(UNIT_SKILLS,id),l=(g.skills[id]||g.unitSkills[id]||0);return `<button class="ability-choice" data-action="choose" data-id="${id}" style="--skill-color:${s.color}"><div class="choice-top"><span class="tag">${s.type}</span><span>${l?'강화':'NEW'}</span></div><span class="choice-symbol">${s.icon}</span><span class="eyebrow">${s.en}</span><h3>${s.name}</h3><p>${s.desc}</p><small>${s.detail}</small><div class="choice-bottom">${l?`Lv.${l} → Lv.${l+1}`:'새로운 초능력'} ${icon('arrow')}</div></button>`;}).join('')}</div><div class="level-footer"><button class="button" data-action="auto-select">자동 선택 ${g.autoSelect?'ON':'OFF'}</button><span>${icon('pause')} 선택하는 동안 시간은 흐르지 않습니다</span><button class="button" data-action="reroll" ${g.rerolls<=0||g.picksLeft!==(save.upgrades.double?2:1)?'disabled':''}>${icon('refresh')} 새로고침 (${g.rerolls})</button></div>`);modal.querySelector('.modal').classList.add('level-modal');}
function pauseMenu(){openModal(`<div class="pause-heading"><span class="eyebrow">OPERATION PAUSED</span><h2>잠시, 숨을 고르고.</h2><p>${game.stage.name} · ${clock(game.time)} · ${game.kills} 처치</p></div><button class="button primary full-width" data-action="resume">${icon('play')} 계속하기</button><button class="button full-width" data-action="equipment">${icon('grid')} 획득 장비 확인</button>${ownedSkills(save,game.skills,selectedRunSkill,game.unitSkills)}<button class="button full-width" data-action="return-confirm">본부로 귀환</button><p class="modal-note">지금 귀환해도 획득한 ${fmt(game.credits)} 에테르는 보존됩니다.</p>`);}
function inventoryPage(){return pageHeader('ARMORY / PERSISTENT GEAR','당신의 힘을, 갖추다.','6개 부위에 하나씩 장착합니다. 획득한 장비와 옵션은 다음 출격에도 그대로 남습니다.')+equipmentMarkup(save,gearView);}
function equipment(){if(game.state==='playing')game.state='paused';keys.clear();joystick=null;openModal(`<div class="equipment-modal-heading"><div><span class="eyebrow">FIELD ARMORY · PAUSED</span><h2>장비 · 인벤토리</h2><p>장비를 확인하는 동안 전투 시간이 멈춥니다.</p></div><button class="button primary" data-action="resume">전투 계속하기 ${icon('play')}</button></div>${ownedSkills(save,game.skills,selectedRunSkill,game.unitSkills)}${equipmentMarkup(save,gearView,{battle:true,skills:game.skills,units:game.unitSkills})}`);modal.querySelector('.modal').classList.add('equipment-modal');}
function refreshEquipment(){if(game&&game.state==='paused'){equipment();updateHud();}else render();}
function showResult(){const clear=game.result==='clear';openModal(`<div class="result-heading"><span class="result-symbol">${icon(clear?'check':'target')}</span><span class="eyebrow">${clear?'OPERATION COMPLETE':game.result==='death'?'SIGNAL LOST':'RETURN TO BASE'}</span><h2>${clear?'이 밤을 넘었습니다.':game.result==='death'?'아직, 끝이 아닙니다.':'다음 밤을 준비하며.'}</h2><p>${clear?'도시는 당신의 이름을 기억할 것입니다.':'이번 각성의 기록은 다음 출격의 힘이 됩니다.'}</p></div><div class="result-stats"><div><span>생존 시간</span><strong>${clock(game.time)}</strong></div><div><span>처치</span><strong>${fmt(game.kills)}</strong></div><div><span>각성 레벨</span><strong>${game.level}</strong></div></div><div class="reward-total"><span>획득 에테르<small>전투 ${Math.floor(game.credits)} + 클리어 ${result?.bonus||0}</small></span><strong>+${fmt(result?.earned||0)}</strong></div>${clear&&game.stage.id<STAGES.length?'<p class="unlock-notice">다음 작전 구역이 해금되었습니다.</p>':''}<p class="modal-note">초능력은 도감에 기록되었습니다. 전투 초능력은 초기화되고 장비와 장착 상태는 유지됩니다.</p><button class="button primary full-width" data-action="lobby">작전 본부로 ${icon('arrow')}</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(a==='nav'){if(starting){startGeneration++;starting=false;}view=b.dataset.view;render();window.scrollTo(0,0);}if(a==='toggle-mode'){if(id==='accelerated')accelerated=!accelerated;else if(id==='endless'&&hasClearedStage(save,stageId))mode=mode==='endless'?'normal':'endless';render();}if(a==='stage'){const allowed=unlockedStage(id,STAGES,save.maxStage);if(allowed){stageId=allowed;render();}}if(a==='character'&&save.unlocked.includes(id)){save.character=id;writeSave();render();}if(a==='upgrade'&&buyUpgrade(save,id)){writeSave();sound('upgrade');toast('연구 완료 · 다음 출격부터 적용됩니다.');render();}if(a==='skill-research'&&buyResearch(save,id,b.dataset.kind)){writeSave();toast('초능력 연구가 완료되었습니다.');render();}if(a==='owned-skill'&&game?.state==='paused'&&game.skills[id]){selectedRunSkill=selectedRunSkill===id?null:id;const panel=b.closest('.owned-skills');panel.outerHTML=ownedSkills(save,game.skills,selectedRunSkill,game.unitSkills);document.querySelector(`.owned-skill-icon[data-id="${id}"]`)?.focus();}if(a==='research-reset'){const target=id==='all'?null:id,preview=researchResetPreview(save,target),name=target?byId(SKILLS,target)?.name:'모든 초능력';if(preview.count)openModal(`<div class="pause-heading"><h2>${name} 연구를 초기화할까요?</h2><p>등장 가중치와 기본 성능 연구 ${preview.count}개 능력을 초기화하고 ${fmt(preview.refund)} 에테르를 돌려받습니다. 도감 등록은 유지됩니다.</p></div><button class="button primary full-width" data-action="research-reset-confirm" data-id="${id}">초기화 · ${fmt(preview.refund)} 에테르 환급</button><button class="button full-width" data-action="close">취소</button>`);}if(a==='research-reset-confirm'){const result=resetResearch(save,id==='all'?null:id);closeModal();if(result.count){writeSave();toast(`${result.count}개 능력 연구 초기화 · ${fmt(result.refund)} 에테르 환급`);}render();}if(a==='claim'&&claimQuest(save,id)){writeSave();toast('퀘스트 보상을 수령했습니다.');render();}if(a==='sound'){save.sound=!save.sound;writeSave();render();}if(a==='help')help();if(a==='close')closeModal();if(a==='start')start();if(a==='choose'&&game.chooseSkill(id)){writeSave();if(game.state==='playing'){closeModal();levelSignature='';}else{levelSignature='';updateHud();}}if(a==='auto-select'&&game){game.setAutoSelect(!game.autoSelect);if(game.state==='playing'&&modalOpen)closeModal();levelSignature='';updateHud();}if(a==='reroll'&&game.reroll()){levelSignature='';updateHud();}if(a==='pause'&&game.state==='playing'){game.pause();pauseMenu();}if(a==='resume'){closeModal();game.state='playing';keys.clear();}if(a==='equipment'&&game&&['playing','paused'].includes(game.state))equipment();if(a==='return-confirm')openModal(`<div class="pause-heading"><span class="eyebrow">RETURN TO BASE</span><h2>작전을 마치고 귀환할까요?</h2><p>${fmt(game.credits)} 에테르는 정산됩니다.<br>이번 전투의 초능력은 초기화됩니다. 장비와 장착 상태는 유지됩니다.</p></div><button class="button primary full-width" data-action="abandon">귀환하고 정산하기</button><button class="button full-width" data-action="resume">전투 계속하기</button>`);if(a==='abandon')game.end('retreat');if(a==='lobby'){game=null;renderer=null;closeModal();view='mission';render();}});
document.addEventListener('keydown',e=>{if(modalOpen&&e.code==='Tab'){const els=[...modal.querySelectorAll('button:not([disabled]),[tabindex="0"]')];if(els.length){if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}}if(!game){if(e.code==='Escape')closeModal();return;}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Space')game.dash();if(['Escape','KeyP'].includes(e.code)){if(game.state==='playing'){game.pause();pauseMenu();}else if(game.state==='paused'){closeModal();game.pause();keys.clear();}}});
document.addEventListener('keyup',e=>keys.delete(e.code));
function autoPause(){keys.clear();joystick=null;const pad=document.querySelector('#joystick i');if(pad)pad.style.transform='translate(0,0)';if(game?.state==='playing'){game.pause();pauseMenu();}}
window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{if(document.hidden)autoPause();});window.addEventListener('resize',()=>renderer?.resize());
document.addEventListener('pointerdown',e=>{if(e.target.closest('#touch-dash')){e.preventDefault();game?.dash();}const pad=e.target.closest('#joystick');if(!pad||game?.state!=='playing')return;e.preventDefault();pad.setPointerCapture(e.pointerId);const r=pad.getBoundingClientRect();joystick={id:e.pointerId,cx:r.left+r.width/2,cy:r.top+r.height/2,x:0,y:0};moveJoystick(e);});
function moveJoystick(e){if(!joystick||joystick.id!==e.pointerId)return;const dx=e.clientX-joystick.cx,dy=e.clientY-joystick.cy,len=Math.hypot(dx,dy),scale=Math.min(1,38/(len||1));joystick.x=dx*scale/38;joystick.y=dy*scale/38;const el=document.querySelector('#joystick i');if(el)el.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
document.addEventListener('pointermove',moveJoystick);for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>{if(joystick?.id===e.pointerId){joystick=null;const el=document.querySelector('#joystick i');if(el)el.style.transform='translate(0,0)';}});
function frame(t){const dt=lastFrame?Math.min((t-lastFrame)/1000,.05):0;lastFrame=t;if(game&&renderer){game.input.x=joystick?.x||((keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0));game.input.y=joystick?.y||((keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0));game.update(dt);renderer.render(game);hudTick+=dt;if(hudTick>.1){updateHud();hudTick=0;}}requestAnimationFrame(frame);}
render();requestAnimationFrame(frame);

document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled||!b.dataset.action.startsWith('gear-'))return;
  const a=b.dataset.action,id=b.dataset.id,battle=!!game&&game.state!=='ended';
  if(a==='gear-cancel-sale'){pendingBulk=null,pendingCraft=null,pendingReroll=null;pendingSale=null;closeModal();return;}
  if(a==='gear-draw'){if(battle)return;const count=Number(id);if(![1,10,100].includes(count)||save.credits<count*1000){toast('에테르가 부족합니다.');return;}const items=drawGear(save,count);writeSave();const counts=Object.entries(items.reduce((a,i)=>(a[i.rarity]=(a[i.rarity]||0)+1,a),{})).map(([k,v])=>`${k.toUpperCase()} ${v}개`).join(' · ');toast(`뽑기 완료 · ${counts}`);refreshEquipment();return;}
  if(a==='gear-enhance'){if(battle)return;const item=save.gear.find(i=>i.uid===id&&i.location==='bag');if(!item)return;const level=item.enhance||0,cost=1000+500*level;if(level>=10||save.credits<cost){toast('에테르가 부족하거나 최대 강화입니다.');return;}openModal(`<div class="pause-heading"><h2>장비 강화 +${level+1}</h2><p>${gearName(item)} · 성공 확률 ${ENHANCE_CHANCES[level]*100}% · ${cost.toLocaleString()} 에테르<br>고정 기본 옵션 배율 ${Math.round(enhancementMultiplier(level)*100)}% → ${Math.round(enhancementMultiplier(level+1)*100)}%<br>실패 시 에테르만 소모하고 강화 단계는 유지됩니다.</p></div><button class="button primary full-width" data-action="gear-enhance-confirm" data-id="${id}">강화 시도</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;}
  if(a==='gear-enhance-confirm'){if(battle)return;const result=enhanceGear(save,id);closeModal();if(result){writeSave();toast(result.success?`강화 성공 · +${result.level}`:'강화 실패 · 단계 유지');}refreshEquipment();return;}
  if(a==='gear-auto-craft'){if(battle||!['bag','warehouse'].includes(id)||gearView.tab!==id)return;const label=id==='warehouse'?'창고':'인벤토리';openModal(`<div class="pause-heading"><h2>${label} 자동 합성</h2><p>${label}의 같은 부위·등급 미장착 UQ 및 EP 장비를 가능한 만큼 합성합니다. 성공 여부와 관계없이 시도마다 재료 2개와 에테르가 소모됩니다. 가장 강화 단계가 높은 장비를 메인으로 유지합니다. 장착 장비와 다른 보관함은 제외합니다.<br>UQ→EP 50% · 1,000 에테르 / EP→LE 30% · 3,000 에테르</p></div><button class="button primary full-width" data-action="gear-auto-craft-confirm" data-id="${id}">자동 합성 시작</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;}
  if(a==='gear-auto-craft-confirm'){if(battle||!['bag','warehouse'].includes(id)||gearView.tab!==id)return;const result=autoCraftGear(save,id);closeModal();if(result.attempts)writeSave();toast(result.attempts?`${result.attempts}회 합성 · ${result.success}회 성공 · ${result.spent.toLocaleString()} 에테르 소모`:'합성 가능한 장비 또는 에테르가 부족합니다.');gearView.selected=null;refreshEquipment();return;}
  if(a==='gear-auto'){if(battle)return;const grade=document.querySelector('#bulk-grade')?.value||'c';save.autoSellGrade=save.autoSellGrade===grade?null:grade;writeSave();toast(save.autoSellGrade?`${grade.toUpperCase()} 이하 자동 판매 켜짐`:'자동 판매 꺼짐');refreshEquipment();return;}
  if(a==='gear-reroll'){if(battle)return;const item=save.gear.find(i=>i.uid===id&&i.location==='bag');if(!item)return;const cost=REROLL_COST[item.rarity];if(save.credits<cost){toast('에테르가 부족합니다.');return;}pendingReroll=id;openModal(`<div class="pause-heading"><h2>장비 옵션을 재설정할까요?</h2><p>${gearName(item)} · ${item.rarity.toUpperCase()}<br>${cost} 에테르를 사용해 모든 랜덤 옵션을 다시 굴립니다.</p></div><button class="button primary full-width" data-action="gear-reroll-confirm" data-id="${id}">재설정 · ${cost} 에테르</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;}
  if(a==='gear-reroll-confirm'){if(battle||id!==pendingReroll)return;const changed=rerollGear(save,id);pendingReroll=null;closeModal();if(changed){writeSave();toast('장비 옵션을 재설정했습니다.');}refreshEquipment();return;}
  if(a==='gear-craft'){if(battle)return;const item=save.gear.find(i=>i.uid===id),ids=[document.querySelector('#craft-1')?.value,document.querySelector('#craft-2')?.value],options=craftCandidates(save,id);if(!item||ids.some(x=>!options.some(i=>i.uid===x))||new Set(ids).size!==2){toast('서로 다른 재료 장비 2개를 선택하세요.');return;}const cost=item.rarity==='uq'?1000:3000;if(save.credits<cost){toast('에테르가 부족합니다.');return;}pendingCraft={id,ids};const target=item.rarity==='uq'?'EP':'LE',chance=item.rarity==='uq'?50:30;openModal(`<div class="pause-heading"><h2>${target} 장비 제작</h2><p>${gearName(item)} · 성공 확률 ${chance}% · ${cost} 에테르<br>선택한 재료 장비 2개는 성공·실패 모두 소멸합니다. 실패 시 메인 장비는 유지됩니다.</p></div><button class="button primary full-width" data-action="gear-craft-confirm" data-id="${id}">제작 시도</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;}
  if(a==='gear-craft-confirm'){if(battle||!pendingCraft||pendingCraft.id!==id)return;const result=craftGear(save,id,pendingCraft.ids);pendingCraft=null;closeModal();if(result){writeSave();toast(result.success?`${result.target.toUpperCase()} 장비 제작 성공`:'제작 실패 · 메인 장비 유지');}refreshEquipment();return;}
  if(a==='gear-bulk'){
    if(battle)return;const grade=gearView.bulkGrade||'c',items=bulkSaleItems(save,grade);if(!items.length){toast('판매 가능한 미장착 장비가 없습니다.');return;}
    pendingBulk={grade,ids:items.map(i=>i.uid)};const price=items.reduce((n,i)=>n+GRADES[i.rarity].sell,0);
    openModal(`<div class="pause-heading"><h2>${grade.toUpperCase()} 이하 장비를 일괄 판매할까요?</h2><p>인벤토리 미장착 장비 ${items.length}개 · ${price} 에테르<br>장착 장비와 창고 장비는 제외됩니다.<br>판매한 장비는 되돌릴 수 없습니다.</p></div><button class="button primary full-width" data-action="gear-confirm-bulk">${items.length}개 판매 · ${price} 에테르</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;
  }
  if(a==='gear-confirm-bulk'){
    if(battle||!pendingBulk)return;const sold=bulkSellGear(save,pendingBulk.grade,pendingBulk.ids);pendingBulk=null,pendingCraft=null,pendingReroll=null;writeSave();closeModal();toast(`${sold.count}개 판매 · +${sold.total} 에테르`);refreshEquipment();return;
  }
  if(a==='gear-confirm-sale'){
    if(battle||id!==pendingSale)return;
    const price=sellGear(save,id);pendingSale=null;closeModal();if(price){writeSave();toast(`장비 판매 · +${price} 에테르`);}refreshEquipment();return;
  }
  if(a==='gear-tab'){if(battle&&id==='warehouse')return;gearView.tab=id;gearView.selected=null;gearView.page=0;}
  if(a==='gear-select'){if(gearView.selected!==id)gearView.craftMaterials=[];gearView.selected=id;}
  if(a==='gear-slot'){gearView.slot=id;gearView.grade='all';gearView.tab='bag';gearView.page=0;gearView.selected=save.equipped[id]||null;}
  if(a==='gear-page')gearView.page+=Number(id);
  if(a==='gear-equip'){const changed=battle?game.equip(id):equipGear(save,id);if(changed){writeSave();toast('장착 완료 · 해당 부위의 장비를 교체했습니다.');}}
  if(a==='gear-unequip'){const changed=battle?game.unequip(id):unequipGear(save,id);if(changed)writeSave();}
  if(a==='gear-move'){if(battle)return;if(moveGear(save,id,b.dataset.destination)){writeSave();gearView.selected=null;toast(b.dataset.destination==='warehouse'?'창고에 수납했습니다.':'인벤토리로 꺼냈습니다.');}}
  if(a==='gear-sell'){
    if(battle)return;const item=save.gear.find(i=>i.uid===id);if(!item||isEquipped(save,id))return;pendingSale=id;
    openModal(`<div class="pause-heading"><span class="eyebrow">SELL EQUIPMENT</span><h2>이 장비를 판매할까요?</h2><p>${gearName(item)} · ${item.rarity.toUpperCase()}<br>${GRADES[item.rarity].sell} 에테르를 받습니다.<br>판매한 장비는 되돌릴 수 없습니다.</p></div><button class="button primary full-width" data-action="gear-confirm-sale" data-id="${id}">${GRADES[item.rarity].sell} 에테르에 판매</button><button class="button full-width" data-action="gear-cancel-sale">취소</button>`);return;
  }
  refreshEquipment();
});
document.addEventListener('change',e=>{if(e.target.id==='gear-slot-filter'){gearView.slot=e.target.value;gearView.page=0;gearView.selected=null;refreshEquipment();}if(e.target.id==='gear-grade-filter'){gearView.grade=e.target.value;gearView.page=0;gearView.selected=null;refreshEquipment();}});
document.addEventListener('keydown',e=>{if(e.code==='KeyI'&&!e.repeat&&game){if(game.state==='playing')equipment();else if(game.state==='paused'){closeModal();game.state='playing';keys.clear();}}});

document.addEventListener('change',e=>{if(e.target.id==='bulk-grade')gearView.bulkGrade=e.target.value;if(e.target.id==='game-mode'&&MODES[e.target.value]){mode=e.target.value;render();}});

document.addEventListener('change',e=>{if(['craft-1','craft-2'].includes(e.target.id)){const index=e.target.id==='craft-1'?0:1;gearView.craftMaterials[index]=e.target.value;refreshEquipment();}});
